/* Phase-one prototype only: deterministic examples, no real model or filesystem. */
(function(root){
  const clone=x=>JSON.parse(JSON.stringify(x));
  const stamp=k=>JSON.stringify(k.files);
  const availableName=(s,base)=>{let name=base,suffix=2;while(s.skills.some(k=>k.name===name))name=base+'-'+suffix++;return name};
  const requireText=(value,label)=>{if(typeof value!=='string'||!value.trim())throw Error('请填写'+label);return value.trim()};
  function manifest(name,description){return `---\nname: ${name}\ndescription: ${JSON.stringify(description)}\n---\n\n# ${name}\n\n## Role\n根据用户提供的材料完成任务。\n\n## Responsibility\n${description}\n\n## Working Method\n先核对输入，再整理结论；不足时说明缺少哪些资料。\n\n## Skill Usage Guidance\n仅调用当前工作区可用的技能。\n\n## Tool Usage Guidance\n仅访问授权测试资源。\n\n## Input Understanding\n明确对象、时间范围和数据口径。\n\n## Output Requirement\n输出结论、依据和待确认事项。\n`}
  function state(){
    const k={name:'weekly-report',title:'周报助手',files:{'SKILL.md':manifest('weekly-report','整理本周进展、风险和下周计划。'),'evals/evals.json':JSON.stringify({skill_name:'weekly-report',evals:[{id:1,prompt:'本周完成两家门店活动；客流有所增长，但没有明确数值。生成周报。',expected_output:'列出活动进展，说明缺少客流数值，不编造增长比例，并给出下周计划。',files:[],expectations:['不编造客流增长比例','有下周计划']},{id:2,prompt:'没有提供任何本周事项，请生成周报。',expected_output:'说明缺少材料并请求补充，不生成虚构进展。',files:[],expectations:['不虚构业务数据']}]},null,2)},protectedIds:[1],report:null};
    return {role:'operator',skills:[k],snippets:[{id:'facts',title:'事实与依据',description:'区分事实、推断和待确认事项。',body:'## 事实与依据\n只依据提供的材料，不编造数据；缺少依据时明确说明。',keywords:['分析','报告','周报','总结']},{id:'sql',title:'SQL 查询规范',description:'查询范围、字段和写入限制。',body:'## SQL 查询规范\n显式列出字段，限制返回行数；不执行未授权写入。',keywords:['SQL','sql','查询','数据']},{id:'output',title:'结果表达',description:'用运营能理解的语言说明结果。',body:'## 结果表达\n先给结论，再给依据；行动建议说明具体对象和下一步。',keywords:['运营','活动','报告','周报']}],generation:null,job:null,savedCalls:{},seq:10};
  }
  function skill(s,name){const k=s.skills.find(k=>k.name===name);if(!k)throw Error('未找到技能');return k}
  function editable(s,k){if(s.job?.state==='running'&&s.job.skill===k.name)throw Error('当前技能正在测评，请结束后再编辑')}
  function readCases(k){const v=JSON.parse(k.files['evals/evals.json']);if(v.skill_name!==k.name||!Array.isArray(v.evals))throw Error('用例文件格式不正确');const ids=new Set();for(const c of v.evals){if(!Number.isInteger(c.id)||c.id<1||ids.has(c.id))throw Error('用例 id 必须唯一且为正整数');ids.add(c.id);requireText(c.prompt,'场景输入');requireText(c.expected_output,'预期结果');if(!Array.isArray(c.files)||c.files.some(f=>typeof f!=='string'||f.startsWith('/')||f.includes('..')||f.includes('\\')))throw Error('输入文件必须为安全相对路径');if(c.expectations!==undefined&&(!Array.isArray(c.expectations)||c.expectations.some(e=>typeof e!=='string'||!e.trim())))throw Error('检查要点格式不正确')};return v}
  function writeCases(s,k,v){editable(s,k);const temp={...k,files:{...k.files,'evals/evals.json':JSON.stringify(v,null,2)}};readCases(temp);for(const id of k.protectedIds)if(!v.evals.some(c=>c.id===id))throw Error('曾发布的用例不可删除');k.files=temp.files}
  function addCase(s,k,input){const v=readCases(k),id=Math.max(0,...v.evals.map(c=>c.id))+1;v.evals.push({id,prompt:requireText(input.prompt,'场景输入'),expected_output:requireText(input.expected_output,'预期结果'),files:input.files||[],expectations:input.expectations||[]});writeCases(s,k,v);return id}
  function deleteCase(s,k,id){const v=readCases(k);v.evals=v.evals.filter(c=>c.id!==id);writeCases(s,k,v)}
  function saveFile(s,k,path,body){if(path==='evals/evals.json')return writeCases(s,k,JSON.parse(body));if(path!=='SKILL.md')throw Error('原型只支持编辑这两个文件');if(!/^---\r?\n/.test(body)||!body.includes('name: '+k.name)||!body.includes('description:'))throw Error('必须保留根 frontmatter、原 name 和 description');k.files[path]=body}
  function startCreate(s,{description}){if(s.generation?.state==='running')throw Error('正在创建，请稍候');description=requireText(description,'技能描述');const base=/周报|weekly/i.test(description)?'weekly-report':/sql|查询/i.test(description)?'query-assistant':/销售|sales/i.test(description)?'sales-analysis':'custom-skill';const name=availableName(s,base);const snippets=s.snippets.filter(x=>x.keywords.some(w=>description.includes(w))&&(x.id!=='sql'||/sql|查询|数据库/i.test(description)));return s.generation={id:++s.seq,state:'running',name,description,snippets:clone(snippets)}}
  function finishCreate(s,job,fail=false){if(job!==s.generation||job.state!=='running')throw Error('创建任务已结束');if(fail){job.state='failed';return null}if(s.skills.some(k=>k.name===job.name)){job.state='failed';throw Error('已有同名技能，未覆盖')};const k={name:job.name,title:job.name,files:{'SKILL.md':manifest(job.name,job.description)+(job.snippets.length?'\n'+job.snippets.map(x=>x.body).join('\n\n'):''),'evals/evals.json':JSON.stringify({skill_name:job.name,evals:[]},null,2)},protectedIds:[],report:null};s.skills.push(k);job.state='completed';return k}
  function writeSnippet(s,value){if(s.role!=='admin')throw Error('仅平台管理员可维护片段');const title=requireText(value.title,'片段名称'),body=requireText(value.body,'片段正文');const old=s.snippets.find(x=>x.id===value.id);if(old)Object.assign(old,{title,body,description:value.description||''});else s.snippets.push({id:'snippet-'+(++s.seq),title,body,description:value.description||'',keywords:[title]})}
  function removeSnippet(s,id){if(s.role!=='admin')throw Error('仅平台管理员可维护片段');s.snippets=s.snippets.filter(x=>x.id!==id)}
  function output(c,improved){const ok=improved||c.id%2===0;return {id:c.id,status:ok?'passed':'failed',messages:[{role:'user',content:c.prompt},{role:'assistant',content:'我先核对已提供的材料与缺失信息。'},{role:'tool',name:'读取测试材料',content:'输入来源：用例授权材料；未访问生产数据。'},...(c.id===1?[{role:'subagent',name:'材料核对',content:'子任务完成：未提供可计算的客流明细，不应推断增长比例。'}]:[]),{role:'assistant',content:ok?'【模拟输出】\n已完成事项：依据提供的材料逐项整理。\n数据说明：材料不足时不推测具体数值，明确列出待补充信息。\n风险：当前依据不足以计算变化比例。\n下一步：补充明细后再分析，并确认下周行动。':'【模拟输出】\n本周活动已完成，客流增长约 20%。\n下周继续活动，跟进转化。\n问题：20% 没有材料依据。'},{role:'file',name:'artifacts/result.md',content:ok?'# 结果\n已整理结论与待补充材料。\n没有虚构数值。':'# 结果\n客流增长约 20%，缺少依据。'}],reason:ok?'模拟判定：符合本用例的预期方向，证据见最终回复。':'模拟判定：出现缺乏依据的数值，未满足预期。'}}
  function startRun(s,k,optimize=false,maxIterations=3){if(s.job?.state==='running')throw Error('已有任务在运行');if(optimize&&(!Number.isInteger(maxIterations)||maxIterations<1||maxIterations>10))throw Error('最大迭代次数需为 1–10 的整数');const cases=clone(readCases(k).evals);if(!cases.length)throw Error('请先添加验证场景');if(!k.files['SKILL.md']?.includes('name: '+k.name))throw Error('静态检查未通过：name 不一致');const missing=cases.flatMap(c=>c.files).find(p=>!Object.hasOwn(k.files,p));if(missing)throw Error('缺少测试输入文件：'+missing);const job={id:++s.seq,skill:k.name,state:'running',phase:'before',cursor:0,optimize,maxIterations:optimize?maxIterations:0,iteration:0,rounds:[],cases,before:[],after:[],beforeFiles:clone(k.files),runFiles:clone(k.files),afterFiles:null,workspaceExpected:stamp(k),expected:stamp(k),written:false};s.job=job;k.report=job;return job}
  function step(s,evaluate=output){const j=s.job;if(!j||j.state!=='running')return j;const k=skill(s,j.skill);
    if(j.phase==='optimize'){j.iteration++;const round={iteration:j.iteration,before:clone(j.iteration===1?j.before:j.after),beforeFiles:clone(j.runFiles),after:[]};j.rounds.push(round);j.after=[];j.runFiles['SKILL.md']+='\n## 根据测评优化 · 第 '+j.iteration+' 次\n缺少材料时明确说明，不得编造任何比例或业务事实。\n';j.optimized=true;j.afterFiles=clone(j.runFiles);round.afterFiles=clone(j.runFiles);if(!j.writebackConflict&&stamp(k)===j.workspaceExpected){k.files=clone(j.runFiles);j.workspaceExpected=stamp(k);j.written=true}else{j.writebackConflict=true}j.expected=stamp({...k,files:j.runFiles});j.phase='after';j.cursor=0;return j}
    j[j.phase].push(evaluate(j.cases[j.cursor],j.phase==='after'||j.runFiles['SKILL.md'].includes('根据测评优化')));j.cursor++;
    if(j.phase==='after')j.rounds.at(-1).after=clone(j.after);
    if(j.cursor===j.cases.length){const results=j[j.phase],passed=results.every(r=>r.status==='passed'),abnormal=results.some(r=>!['passed','failed'].includes(r.status));
      if(!j.optimize){j.state='completed';return j}
      if(abnormal){j.state='failed';j.stopReason='evaluation_error';j.reason='测评异常，已停止自动优化';return j}
      if(passed){j.state='completed';j.stopReason='all_passed';j.reason=j.iteration?'全部用例通过，提前结束':'前测已全部通过，无需优化';return j}
      if(j.phase==='after'&&j.iteration>=j.maxIterations){j.state='completed';j.stopReason='max_iterations';j.reason='已达到最大迭代次数，仍有用例未通过';return j}
      j.phase='optimize';
    }return j;
  }
  function stop(s){if(s.job?.state==='running')s.job.state='cancelled'}
  function invocation(s,k,query){requireText(query,'任务内容');return {id:'call-'+(++s.seq),skill:k.name,prompt:query,result:output({id:2,prompt:query},true),saved:false}}
  function saveInvocation(s,call){if(s.savedCalls[call.id])return s.savedCalls[call.id];const k=skill(s,call.skill),actual=call.result.messages.filter(m=>m.role==='assistant').at(-1).content;const id=addCase(s,k,{prompt:call.prompt,expected_output:actual,files:[],expectations:[]});s.savedCalls[call.id]=id;call.saved=true;return id}
  root.PhaseOneModel={state,skill,stamp,readCases,addCase,deleteCase,saveFile,startCreate,finishCreate,writeSnippet,removeSnippet,startRun,step,stop,invocation,saveInvocation,clone};
})(globalThis);
